diff --git a/src/export.js b/src/export.js
index e1329a4..cd563d3 100644
--- a/src/export.js
+++ b/src/export.js
@@ -1,15 +1,38 @@
 import { writeCsv } from "./csv.js";
-import { formatAmount } from "./amount.js";
+import { formatAmount, parseAmount } from "./amount.js";

-/** Render a ledger as "csv" (rows plus a TOTAL row) or "json" ({ locale, records, total } in cents). */
-export function renderExport(ledger, { format = "csv" } = {}) {
-  const total = ledger.records.reduce((sum, record) => sum + record.amount, 0);
-  if (format === "json") return JSON.stringify({ locale: ledger.locale, records: ledger.records, total }, null, 2) + "\n";
+/**
+ * Parse a minimum-amount threshold written like the ledger's own amounts (same locale, optional currency prefix).
+ * Throws RangeError if it cannot be parsed or is negative.
+ */
+function parseMinAmount(text, locale) {
+  let cents;
+  try {
+    cents = parseAmount(text, { locale });
+  } catch {
+    throw new RangeError(`invalid min amount: ${JSON.stringify(text)}`);
+  }
+  if (cents < 0 || Object.is(cents, -0)) throw new RangeError(`min amount must not be negative: ${JSON.stringify(text)}`);
+  return cents;
+}
+
+/**
+ * Render a ledger as "csv" (rows plus a TOTAL row) or "json" ({ locale, records, total } in cents).
+ * minAmount (optional string): keep only records whose absolute amount is at least this; the total covers kept records.
+ */
+export function renderExport(ledger, { format = "csv", minAmount } = {}) {
+  let records = ledger.records;
+  if (minAmount !== undefined) {
+    const threshold = parseMinAmount(minAmount, ledger.locale);
+    records = records.filter((record) => Math.abs(record.amount) >= threshold);
+  }
+  const total = records.reduce((sum, record) => sum + record.amount, 0);
+  if (format === "json") return JSON.stringify({ locale: ledger.locale, records, total }, null, 2) + "\n";
   if (format !== "csv") throw new RangeError(`unknown format: ${format}`);
   const amount = (cents) => formatAmount(cents, { locale: ledger.locale });
   return writeCsv([
     ["date", "account", "description", "amount"],
-    ...ledger.records.map((r) => [r.date, r.account, r.description, amount(r.amount)]),
+    ...records.map((r) => [r.date, r.account, r.description, amount(r.amount)]),
     ["", "", "TOTAL", amount(total)],
   ]);
 }
