   const out = execFileSync("node", ["bin/ledger.js", "export", "--format", "json", "data/q3-en.csv"], { encoding: "utf8" });
   assert.equal(JSON.parse(out).records.length, 6);
 });
+
+test("minAmount keeps |amount| >= threshold and totals only kept records", () => {
+  const en = JSON.parse(exportFile("data/q3-en.csv", { format: "json", minAmount: "$1,000.00" }));
+  assert.deepEqual(en.records.map((r) => r.amount), [1250000, 100000, -100000]);
+  assert.equal(en.total, 1250000);
+
+  const de = exportFile("data/q3-de.csv", { minAmount: "€ 1.234,50" });
+  assert.equal(de, 'date,account,description,amount\n2026-07-03,4000,Beratung,"8.400,00"\n2026-07-08,6100,Büromaterial,"-1.234,50"\n,,TOTAL,"7.165,50"\n');
+});
+
+test("minAmount rejects negative or unparseable thresholds with RangeError", () => {
+  for (const minAmount of ["-1.00", "(5.00)", "−5", "abc", "", "1.000,00", 1000]) {
+    assert.throws(() => exportFile("data/q3-en.csv", { minAmount }), RangeError, String(minAmount));
+  }
+  assert.throws(() => exportFile("data/q3-de.csv", { minAmount: "1,234.50" }), RangeError);
+});
+
+test("CLI --min-amount before or after the file, and invalid value", () => {
+  for (const args of [["--min-amount", "1,000.00", "data/q3-en.csv"], ["data/q3-en.csv", "--min-amount", "1,000.00"]]) {
+    const out = execFileSync("node", ["bin/ledger.js", "export", ...args], { encoding: "utf8" });
+    assert.match(out, /,,TOTAL,"12,500.00"\n$/);
+    assert.equal(out.trim().split("\n").length, 5);
+  }
+  assert.throws(
+    () => execFileSync("node", ["bin/ledger.js", "export", "data/q3-en.csv", "--min-amount", "-5"], { stdio: "pipe" }),
+    (error) => error.status === 2 && /error: min amount must not be negative/.test(error.stderr) && /usage:/.test(error.stderr),
+  );
+  assert.throws(() => execFileSync("node", ["bin/ledger.js", "export", "data/q3-en.csv", "--min-amount"], { stdio: "pipe" }),
+    (error) => error.status === 2 && /--min-amount needs a value/.test(error.stderr));
+});

args.command:
cat >> test/export.test.js <<'EOF'

test("minAmount keeps |amount| >= threshold and totals only kept records", () => {
  const en = JSON.parse(exportFile("data/q3-en.csv", { format: "json", minAmount: "$1,000.00" }));
  assert.deepEqual(en.records.map((r) => r.amount), [1250000, 100000, -100000]);
  assert.equal(en.total, 1250000);

  const de = exportFile("data/q3-de.csv", { minAmount: "€ 1.234,50" });
  assert.equal(de, 'date,account,description,amount\n2026-07-03,4000,Beratung,"8.400,00"\n2026-07-08,6100,Büromaterial,"-1.234,50"\n,,TOTAL,"7.165,50"\n');
});

test("minAmount rejects negative or unparseable thresholds with RangeError", () => {
  for (const minAmount of ["-1.00", "(5.00)", "−5", "abc", "", "1.000,00", 1000]) {
    assert.throws(() => exportFile("data/q3-en.csv", { minAmount }), RangeError, String(minAmount));
  }
  assert.throws(() => exportFile("data/q3-de.csv", { minAmount: "1,234.50" }), RangeError);
});

test("CLI --min-amount before or after the file, and invalid value", () => {
  for (const args of [["--min-amount", "1,000.00", "data/q3-en.csv"], ["data/q3-en.csv", "--min-amount", "1,000.00"]]) {
    const out = execFileSync("node", ["bin/ledger.js", "export", ...args], { encoding: "utf8" });
    assert.match(out, /,,TOTAL,"12,500.00"\n$/);
    assert.equal(out.trim().split("\n").length, 5);
  }
  assert.throws(
    () => execFileSync("node", ["bin/ledger.js", "export", "data/q3-en.csv", "--min-amount", "-5"], { stdio: "pipe" }),
    (error) => error.status === 2 && /error: invalid min amount/.test(error.stderr) && /usage:/.test(error.stderr),
  );
  assert.throws(() => execFileSync("node", ["bin/ledger.js", "export", "data/q3-en.csv", "--min-amount"], { stdio: "pipe" }),
    (error) => error.status === 2 && /--min-amount needs a value/.test(error.stderr));
});
EOF
git stash -q && for f in data/*.csv; do node bin/ledger.js export $f > /tmp/before-$(basename $f).csv; node bin/ledger.js export $f --format json > /tmp/before-$(basename $f).json; done; git stash pop -q
for f in data/*.csv; do node bin/ledger.js export $f | cmp - /tmp/before-$(basename $f).csv && node bin/ledger.js export $f --format json | cmp - /tmp/before-$(basename $f).json && echo "unchanged $f"; done
npm test 2>&1 | tail -15; node bin/ledger.js export data/q3-de.csv --min-amount "abc"; echo "exit=$?"

