+function parseMinAmount(text, locale) {
+  let cents;
+  try {
+    cents = parseAmount(text, { locale });
+  } catch (error) {
+    throw new RangeError(`invalid min amount: ${JSON.stringify(text)} (${error.message})`);
+  }
+  if (!Number.isSafeInteger(cents)) throw new RangeError(`invalid min amount: ${JSON.stringify(text)}`);
+  if (cents < 0) throw new RangeError(`min amount must not be negative: ${JSON.stringify(text)}`);
