cat >> test/export.test.js <<'EOF'

test("minAmount keeps records with |amount| >= threshold and totals only those", () => {
  const out = exportFile("data/q3-en.csv", { minAmount: "1,000.00" });
  assert.equal(
    out,
    'date,account,description,amount\n2026-07-02,4000,Consulting retainer,"12,500.00"\n' +
      '2026-07-09,6200,"Travel, Berlin","1,000.00"\n2026-07-21,6100,Refund,"-1,000.00"\n,,TOTAL,"12,500.00"\n',
  );
  assert.equal(JSON.parse(exportFile("data/q3-en.csv", { minAmount: "$1000", format: "json" })).total, 1250000);
});

test("minAmount uses the file's locale", () => {
  const out = JSON.parse(exportFile("data/q3-de.csv", { format: "json", minAmount: "€ 1.234,50" }));
  assert.deepEqual(out.records.map((r) => r.amount), [840000, -123450]);
  assert.equal(out.total, 840000 - 123450);
  assert.throws(() => exportFile("data/q3-de.csv", { minAmount: "1,234.50" }), RangeError);
});

test("minAmount rejects negative or unparsable thresholds", () => {
  for (const minAmount of ["-1.00", "(5.00)", "−5", "abc", "", "1.234", 100]) {
    assert.throws(() => exportFile("data/q3-en.csv", { minAmount }), RangeError, String(minAmount));
  }
});

test("minAmount undefined leaves output unchanged; zero keeps everything", () => {
  const plain = exportFile("data/q3-en.csv");
  assert.equal(exportFile("data/q3-en.csv", { minAmount: undefined }), plain);
  assert.equal(exportFile("data/q3-en.csv", { minAmount: "0" }), plain);
});

test("CLI --min-amount before or after the file, and input errors", () => {
  const run = (...args) => execFileSync("node", ["bin/ledger.js", "export", ...args], { encoding: "utf8" });
  const after = run("data/q3-en.csv", "--min-amount", "1,000.00");
  assert.equal(run("--min-amount", "1,000.00", "data/q3-en.csv"), after);
  assert.equal(after, exportFile("data/q3-en.csv", { minAmount: "1,000.00" }));
  for (const args of [["data/q3-en.csv", "--min-amount", "-5"], ["data/q3-en.csv", "--min-amount", "x"], ["data/q3-en.csv", "--min-amount"]]) {
    assert.throws(() => run(...args), (error) => error.status === 2 && /^error: .*\nusage: /.test(error.stderr));
  }
});
EOF
