    assert.throws(() => exportFile("data/q3-en.csv", { minAmount }), RangeError, String(minAmount));
  }
});

test("CLI --min-amount before or after file, errors exit 2", () => {
  const run = (...args) => execFileSync("node", ["bin/ledger.js", "export", ...args], { encoding: "utf8" });
  assert.equal(run("--min-amount", "1000", "--format", "json", "data/q3-en.csv"), run("data/q3-en.csv", "--format", "json", "--min-amount", "1000"));
  assert.equal(JSON.parse(run("data/q3-en.csv", "--format", "json", "--min-amount", "1000")).records.length, 3);
  assert.throws(() => execFileSync("node", ["bin/ledger.js", "export", "data/q3-en.csv", "--min-amount", "-5"], { stdio: "pipe" }), (e) => e.status === 2 && /error: .*negative/.test(e.stderr));
});
EOF
