node bin/ledger.js export data/q3-en.csv | cmp - /tmp/a1 && node bin/ledger.js export data/q3-de.csv --format json | cmp - /tmp/a2 && echo SAME
npm test 2>&1 | tail -12
node bin/ledger.js export data/q3-de.csv --min-amount '1.234,50'; node bin/ledger.js export data/q3-en.csv --min-amount; echo "exit $?"; node bin/ledger.js export data/q3-en.csv --min-amount 1.000,00; echo "exit $?"

