 /**
  * Programmatic entry point used by the reporting service.
  * options.format: "csv" (default) or "json".
+ * options.minAmount: optional threshold string written like the file's amounts (same locale, optional currency
+ *   prefix). Only records whose absolute amount is >= the threshold are exported, and totals cover only those.
+ *   Throws RangeError for a negative or unparseable threshold.
  */
 export function exportFile(path, options = {}) {
-  return renderExport(readLedger(path), options);
+  const { minAmount, ...renderOptions } = options;
+  const ledger = readLedger(path);
+  if (minAmount === undefined) return renderExport(ledger, renderOptions);
+  const threshold = parseThreshold(minAmount, ledger.locale);
+  const records = ledger.records.filter((record) => Math.abs(record.amount) >= threshold);
+  return renderExport({ ...ledger, records }, renderOptions);
+}
+
+function parseThreshold(text, locale) {
+  let cents;
+  try {
+    cents = parseAmount(text, { locale });
+  } catch {
+    throw new RangeError(`invalid minimum amount: ${JSON.stringify(text)}`);
+  }
+  // Object.is catches "-0" / "(0)": written as negative even though the value is zero.
+  if (cents < 0 || Object.is(cents, -0)) throw new RangeError(`minimum amount must not be negative: ${JSON.stringify(text)}`);
+  return cents;
 }
