import fs from "node:fs";
import path from "node:path";
const files = ["src/services", "src/jobs"].flatMap((d) => fs.readdirSync(d).map((f) => path.join(d, f)));
const esc = (s) => s.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
for (const file of files) {
  let src = fs.readFileSync(file, "utf8");
  const imp = src.match(/^import (\{[^}]*\}|\* as (\w+)) from "\.\.\/log\.js";$/m);
  if (!imp) continue;
  let callee, newImport;
  if (imp[2]) { callee = `${imp[2]}.log`; newImport = `import { logger } from "../log.js";`; }
  else {
    const specs = imp[1].slice(1, -1).split(",").map((s) => s.trim());
    const logSpec = specs.find((s) => /^log(\s+as\s+\w+)?$/.test(s));
    callee = logSpec.split(/\s+as\s+/).pop();
    newImport = `import { ${specs.map((s) => (s === logSpec ? "logger" : s)).join(", ")} } from "../log.js";`;
  }
  // Protect lines where `log` is not the imported function: comments, shadowing scopes.
  const lines = src.split("\n");
  const prot = new Set();
  let depth = 0, inShadow = false;
  lines.forEach((l, i) => {
    if (/^\s*\/\//.test(l) || /^\s*\/\*\*/.test(l)) prot.add(i);
    if (/function \w+\(log\b/.test(l) || /\bconst log\b/.test(l)) inShadow = true, depth = 0, (/\bconst log\b/.test(l) ? (depth = -1) : 0);
    if (inShadow) {
      prot.add(i);
      depth += (l.match(/\{/g) || []).length - (l.match(/\}/g) || []).length;
      if (depth <= 0 && !/\bconst log\b/.test(l) || depth < -1) inShadow = false;
    }
  });
  const saved = [];
  const masked = lines.map((l, i) => (prot.has(i) ? (saved.push(l), `\u0000${saved.length - 1}\u0000`) : l)).join("\n");
  const C = `(?<![\\w.$])${esc(callee)}`;
  let out = masked.replace(imp[0], newImport)
    .replace(new RegExp(`${C}\\((\\s*)"(debug|info|warn|error)",\\s*`, "g"), "logger.$2($1")
    .replace(new RegExp(`${C}\\((\\s*)([A-Za-z_$][\\w$]*),\\s*`, "g"), "logger[$2]($1");
  const left = out.match(new RegExp(`${C}\\b`, "g"));
  if (left) console.log("REMAINING", file, left);
  out = out.replace(/\u0000(\d+)\u0000/g, (_, n) => saved[n]);
  fs.writeFileSync(file, out);
  console.log(file, "callee:", callee, "protected lines:", [...prot].map((i) => i + 1).join(","));
}
EOF
