cat > /tmp/logmig/migrate.mjs <<'EOF'
import fs from "node:fs";
const files = process.argv.slice(2);
for (const file of files) {
  let src = fs.readFileSync(file, "utf8");
  // Determine callee name bound to src/log.js's log
  let callee;
  if (/^import \{ log as (\w+) \} from "\.\.\/log\.js";$/m.test(src)) callee = RegExp.$1;
  else if (/^import \* as (\w+) from "\.\.\/log\.js";$/m.test(src)) callee = RegExp.$1 + "\\.log";
  else if (/^import \{[^}]*\blog\b[^}]*\} from "\.\.\/log\.js";$/m.test(src)) callee = "log";
  else continue;
  const lines = src.split("\n");
  let skipUntil = null; // regex of closing line for shadowed scope
  const re = new RegExp(`(?<![.\\w$])${callee}\\((\\s*)(?:"(debug|info|warn|error)"|(level)),[ \\t]*`, "g");
  for (let i = 0; i < lines.length; i++) {
    const l = lines[i];
    if (skipUntil) { if (skipUntil.test(l)) skipUntil = null; continue; }
    if (/^export function \w+\(log\b/.test(l)) { skipUntil = /^}/; continue; }
    if (/^\s*const log = /.test(l)) { skipUntil = /^\s*}\s*$/; continue; }
    if (/^\s*\/\//.test(l) || /^import /.test(l)) continue;
    // multi-line form: callee( at line end, level on next line
    lines[i] = l.replace(re, (_, ws, lit, v) => `logger${lit ? "." + lit : "[" + v + "]"}(`);
    if (new RegExp(`(?<![.\\w$])${callee}\\($`).test(l.trimEnd())) {
      const m = lines[i + 1].match(/^(\s*)"(debug|info|warn|error)",\s*$/);
      if (!m) throw new Error(`${file}:${i + 1} unexpected multi-line form`);
      lines[i] = l.replace(new RegExp(`(?<![.\\w$])${callee}\\($`), `logger.${m[2]}(`);
      lines.splice(i + 1, 1);
    }
  }
  src = lines.join("\n");
  // Fix imports
  src = src.replace(/^import \{ log as \w+ \} from "\.\.\/log\.js";$/m, 'import { logger } from "../log.js";')
           .replace(/^import \* as \w+ from "\.\.\/log\.js";$/m, 'import { logger } from "../log.js";')
           .replace(/^import \{([^}]*)\} from "\.\.\/log\.js";$/m, (_, names) =>
             `import { ${names.split(",").map((s) => s.trim()).filter(Boolean).map((n) => (n === "log" ? "logger" : n)).join(", ")} } from "../log.js";`);
  fs.writeFileSync(file, src);
}
EOF
