import fs from "node:fs";
const LEVELS = ["debug", "info", "warn", "error"];
const files = process.argv.slice(2);
for (const file of files) {
  let src = fs.readFileSync(file, "utf8");
  const lines = src.split("\n");
  const imp = lines.findIndex((l) => /from "\.\.\/log\.js";$/.test(l));
  const m = lines[imp].match(/^import (?:\{ (.*) \}|\* as (\w+)) from/);
  let callee, keep = [];
  if (m[2]) { callee = `${m[2]}\\.log`; }
  else {
    const specs = m[1].split(", ");
    const ls = specs.find((s) => /^log( as \w+)?$/.test(s));
    callee = ls.includes(" as ") ? ls.split(" as ")[1] : "log";
    keep = specs.filter((s) => s !== ls);
  }
  // excluded line ranges: scopes where `log` is shadowed
  const excluded = new Set();
  lines.forEach((l, i) => {
    if (/^export function \w+\(log\b/.test(l)) { for (let j = i; j < lines.length && (j === i || lines[j - 1] !== "}"); j++) excluded.add(j); }
    if (/^\s+const log = /.test(l)) { const ind = lines[i - 1].match(/^\s*/)[0]; for (let j = i; j < lines.length && lines[j] !== `${ind}}`; j++) excluded.add(j); }
    if (/^\s*(\/\/|\*|\/\*)/.test(l)) excluded.add(i);
  });
  // offsets -> line
  const lineAt = (off) => src.slice(0, off).split("\n").length - 1;
  const re = new RegExp(`(?<![\\w$.])${callee}\\((\\s*)("(\\w+)"|[A-Za-z_$][\\w$]*),(\\s*)`, "g");
  let count = 0;
  src = src.replace(re, (all, ws1, lvl, lit, ws2, off) => {
    if (excluded.has(lineAt(off))) return all;
    if (lit && !LEVELS.includes(lit)) throw new Error(`${file}: unknown level ${lit}`);
    count++;
    const head = lit ? `logger.${lit}(` : `logger[${lvl}](`;
    return head + (ws1 ? ws2 : "");
  });
  const newImport = `import { ${[...keep, "logger"].join(", ")} } from "../log.js";`;
  src = src.replace(lines[imp], newImport);
  fs.writeFileSync(file, src);
  console.log(file, count);
}
