 import { readLedger } from "./read.js";
 import { renderExport } from "./export.js";
+import { parseAmount } from "./amount.js";

 /**
  * Programmatic entry point used by the reporting service.
  * options.format: "csv" (default) or "json".
+ * options.minAmount: optional threshold written like the file's amounts (its locale, optional currency prefix).
+ *   Only records whose absolute amount is at least the threshold are exported; totals cover exported records only.
+ *   Throws RangeError for a negative or unparseable threshold.
