-export function exportFile(path, options = {}) {
-  return renderExport(readLedger(path), options);
+export function exportFile(path, { minAmount, ...options } = {}) {
+  let ledger = readLedger(path);
+  if (minAmount !== undefined) {
+    const threshold = parseThreshold(minAmount, ledger.locale);
+    ledger = { ...ledger, records: ledger.records.filter((record) => Math.abs(record.amount) >= threshold) };
+  }
+  return renderExport(ledger, options);
+}
+
+function parseThreshold(text, locale) {
+  let cents;
+  try {
+    cents = parseAmount(text, { locale });
+  } catch {
+    throw new RangeError(`invalid minimum amount for locale ${locale}: ${JSON.stringify(text)}`);
+  }
+  // Object.is catches "-0.00" / "(0.00)", which are written as negatives.
+  if (cents < 0 || Object.is(cents, -0)) throw new RangeError(`minimum amount must not be negative: ${JSON.stringify(text)}`);
+  return cents;
 }
