-/** Parse "key: value" lines. Blank lines and lines starting with # are ignored. */
+/**
+ * Remove a trailing comment from the raw value text after the colon. A `#` starts a comment only outside a
+ * quoted string and when preceded by whitespace; `a#b` and `"x#y"` keep their `#`.
+ */
+export function stripComment(raw) {
+  let i = raw.search(/\S/);
+  if (i < 0) return raw;
+  if (raw[i] === '"') {
+    for (i++; i < raw.length && raw[i] !== '"'; i++) if (raw[i] === "\\") i++;
+    if (i >= raw.length) return raw; // unterminated: let parseValue report it
+  }
+  for (; i < raw.length; i++) {
+    if (raw[i] === "#" && /\s/.test(raw[i - 1] ?? "")) return raw.slice(0, i);
+  }
+  return raw;
+}
+
+/** Parse "key: value" lines. Blank lines and lines starting with # are ignored; trailing comments are removed. */
 export function parseConfig(text) {
   const config = {};
   text.split(/\r?\n/).forEach((line, index) => {
     if (line.trim() === "" || line.trim().startsWith("#")) return;
     const match = /^\s*([A-Za-z_][\w.]*)\s*:(.*)$/.exec(line);
     if (!match) throw new SyntaxError(`line ${index + 1}: expected "key: value"`);
-    config[match[1]] = parseValue(match[2]);
+    config[match[1]] = parseValue(stripComment(match[2]));
   });
   return config;
 }
