  let src = fs.readFileSync(file, "utf8");
  let callee;
  if (/import \* as logging from "\.\.\/log\.js";/.test(src)) callee = "logging\\.log";
  else if (/import \{ log as trace \} from/.test(src)) { callee = "trace"; src = src.replace("{ log as trace }", "{ logger }"); }
  else { callee = "log"; src = src.replace(/import \{ (LEVELS, )?log \} from/, "import { $1logger } from"); }
  const target = callee.startsWith("logging") ? "logging.logger" : "logger";
  const [a, b] = skip[file] ?? [0, -1];
  const lines = src.split("\n");
  // Join so multi-line calls `log(\n "warn",` are handled; protect skipped lines/comments.
  const out = [];
  for (let i = 0; i < lines.length; i++) {
    const n = i + 1, line = lines[i];
    if ((n >= a && n <= b) || /^\s*\/\//.test(line) || /^import /.test(line)) { out.push(line); continue; }
    let l = line
      .replace(new RegExp(`(?<![.\\w])${callee}\\("(debug|info|warn|error)", `, "g"), `${target}.$1(`)
      .replace(new RegExp(`(?<![.\\w])${callee}\\(level, `, "g"), `${target}[level](`);
    if (new RegExp(`(?<![.\\w])${callee}\\($`).test(l)) {
      const m = lines[i + 1].match(/^\s*"(debug|info|warn|error)",$/);
      if (!m) throw new Error(`${file}:${n} unexpected multi-line call`);
      l = l.replace(new RegExp(`${callee}\\($`), `${target}.${m[1]}(`);
      i++; // drop level line
    }
    out.push(l);
  }
  fs.writeFileSync(file, out.join("\n"));
}
