+/**
+ * Remove a trailing comment from a raw value: `#` outside a quoted string that follows whitespace.
+ * Index 0 follows the `:` separator, so `#` there is part of the value.
+ */
+function stripComment(raw) {
+  let canOpen = raw.trimStart().startsWith('"');
+  let inString = false;
+  for (let i = 0; i < raw.length; i++) {
+    const char = raw[i];
+    if (inString) {
+      if (char === "\\") i++;
+      else if (char === '"') inString = false;
+    } else if (char === '"' && canOpen) {
+      inString = true;
+      canOpen = false;
+    } else if (char === "#" && i > 0 && /\s/.test(raw[i - 1])) {
+      return raw.slice(0, i);
+    }
+  }
+  return raw;
+}
+
+/** Parse "key: value" lines. Blank lines and comments (see README) are ignored. */
