cd <scratch>/runs/3646078fbf984c63/work/project && cat >> test/export.test.js <<'EOF'

test("minAmount keeps |amount| >= threshold, equal included, and totals only exported records", () => {
  const out = exportFile("data/q3-en.csv", { minAmount: "1,000.00" });
  assert.equal(
    out,
    'date,account,description,amount\n2026-07-02,4000,Consulting retainer,"12,500.00"\n' +
      '2026-07-09,6200,"Travel, Berlin","1,000.00"\n2026-07-21,6100,Refund,"-1,000.00"\n,,TOTAL,"12,500.00"\n',
  );
  const json = JSON.parse(exportFile("data/q3-en.csv", { format: "json", minAmount: "$999.99" }));
  assert.deepEqual(json.records.map((r) => r.amount), [1250000, 100000, 99999, -100000]);
  assert.equal(json.total, 1250000 + 99999);
});

test("minAmount uses the file's locale and currency prefixes", () => {
  const json = JSON.parse(exportFile("data/q3-de.csv", { format: "json", minAmount: "€ 1.234,50" }));
  assert.deepEqual(json.records.map((r) => r.amount), [840000, -123450]);
  assert.equal(json.total, 840000 - 123450);
  assert.match(exportFile("data/q3-de.csv", { minAmount: "1.234,50" }), /,,TOTAL,"7\.165,50"\n$/);
  assert.equal(JSON.parse(exportFile("data/q3-de.csv", { format: "json", minAmount: "0" })).records.length, 5);
  assert.equal(JSON.parse(exportFile("data/q3-de.csv", { format: "json", minAmount: "100000" })).total, 0);
});

test("minAmount rejects negative or unparseable thresholds with RangeError", () => {
  for (const minAmount of ["-1.00", "(5.00)", "−5.00", "-0", "abc", "", "1,000.00", 100, "1.000,00 EUR"]) {
    assert.throws(() => exportFile("data/q3-de.csv", { minAmount }), RangeError, String(minAmount));
  }
  assert.throws(() => exportFile("data/q3-en.csv", { minAmount: "1.000,00" }), RangeError);
});

test("CLI --min-amount before or after the file; bad values reported like other input errors", () => {
  const run = (...args) => execFileSync("node", ["bin/ledger.js", "export", ...args], { encoding: "utf8" });
  const before = run("--min-amount", "1,000.00", "--format", "json", "data/q3-en.csv");
  const after = run("data/q3-en.csv", "--format", "json", "--min-amount", "1,000.00");
  assert.equal(before, after);
  assert.equal(JSON.parse(after).records.length, 3);
  for (const args of [["data/q3-en.csv", "--min-amount", "-5"], ["data/q3-en.csv", "--min-amount", "x"], ["data/q3-en.csv", "--min-amount"]]) {
    const result = spawnSync("node", ["bin/ledger.js", "export", ...args], { encoding: "utf8" });
    assert.equal(result.status, 2, args.join(" "));
    assert.equal(result.stdout, "");
    assert.match(result.stderr, /^error: .*\nusage: ledger export/);
  }
});
EOF
