    callee = "trace";
    src = src.replace('import { log as trace } from "../log.js";', 'import { logger } from "../log.js";');
  } else if (/import \* as logging from "\.\.\/log\.js";/.test(src)) {
    callee = "logging\\.log"; prefix = "logging.logger";
  } else if (/import \{ LEVELS, log \} from "\.\.\/log\.js";/.test(src)) {
    callee = "log";
    src = src.replace('import { LEVELS, log } from "../log.js";', 'import { LEVELS, logger } from "../log.js";');
  } else if (/import \{ log \} from "\.\.\/log\.js";/.test(src)) {
    callee = "log";
    src = src.replace('import { log } from "../log.js";', 'import { logger } from "../log.js";');
  } else { console.log("SKIP", file); continue; }
  const ranges = exclude[file] ?? [];
  const lineOf = (i) => src.slice(0, i).split("\n").length;
  const lineText = (n) => src.split("\n")[n - 1];
  const re = new RegExp(`(?<![.\\w])${callee}\\(\\s*(?:"(\\w+)"|(level)),\\s*`, "g");
  let count = 0;
  src = src.replace(re, (m, lit, v, idx) => {
    const n = lineOf(idx);
    if (ranges.some(([a, b]) => n >= a && n <= b)) return m;
    if (/^\s*(\/\/|\*|\/\*)/.test(lineText(n))) return m;
    count++;
    return lit ? `${prefix}.${lit}(` : `${prefix}[${v}](`;
  });
  fs.writeFileSync(file, src);
  console.log(file, count);
}
