+const cli = (...args) => spawnSync("node", ["bin/ledger.js", ...args], { encoding: "utf8" });
+
+test("minAmount: absolute value, inclusive, total over exported records (en)", () => {
+  const out = JSON.parse(exportFile("data/q3-en.csv", { format: "json", minAmount: "$1,000.00" }));
+  assert.deepEqual(out.records.map((r) => r.amount), [1250000, 100000, -100000]);
+  assert.equal(out.total, 1250000);
+  const csv = exportFile("data/q3-en.csv", { minAmount: "1,000.00" });
+  assert.equal(
+    csv,
+    "date,account,description,amount\n" +
+      '2026-07-02,4000,Consulting retainer,"12,500.00"\n' +
+      '2026-07-09,6200,"Travel, Berlin","1,000.00"\n' +
+      '2026-07-21,6100,Refund,"-1,000.00"\n' +
+      ',,TOTAL,"12,500.00"\n',
+  );
+});
+
+test("minAmount uses the file's locale (de)", () => {
+  const out = JSON.parse(exportFile("data/q3-de.csv", { format: "json", minAmount: "€ 1.234,50" }));
+  assert.deepEqual(out.records.map((r) => r.amount), [840000, -123450]);
+  assert.equal(out.total, 840000 - 123450);
+  assert.match(exportFile("data/q3-de.csv", { minAmount: "1.234,50" }), /,,TOTAL,"7\.165,50"\n$/);
+  assert.throws(() => exportFile("data/q3-de.csv", { minAmount: "1,234.50" }), RangeError);
+});
+
+test("minAmount: zero keeps everything, above all keeps nothing", () => {
+  assert.equal(exportFile("data/q3-en.csv", { minAmount: "0" }), exportFile("data/q3-en.csv"));
+  const out = JSON.parse(exportFile("data/q3-en.csv", { format: "json", minAmount: "100000" }));
