for (const rel of files) {
  const file = path.join(root, rel);
  let lines = fs.readFileSync(file, "utf8").split("\n");
  let callee;
  const imp = lines[1];
  let m;
  if ((m = imp.match(/^import \{ log as (\w+) \} from "\.\.\/log\.js";$/))) { callee = m[1]; lines[1] = 'import { logger } from "../log.js";'; }
  else if (imp === 'import { log } from "../log.js";') { callee = "log"; lines[1] = 'import { logger } from "../log.js";'; }
  else if (imp === 'import { LEVELS, log } from "../log.js";') { callee = "log"; lines[1] = 'import { LEVELS, logger } from "../log.js";'; }
  else if (imp === 'import * as logging from "../log.js";') { callee = "logging.log"; lines[1] = 'import { logger } from "../log.js";'; }
  else throw new Error("unknown import in " + rel + ": " + imp);
  const esc = callee.replace(".", "\\.");
  const src0 = lines.map((l, i) => [l, i + 1]);
  const out = [];
  for (let i = 0; i < lines.length; i++) {
    const ln = i + 1;
    let l = lines[i];
    if (ln === 2 || (skip[rel] || []).includes(ln) || l.trim().startsWith("//")) { out.push(l); continue; }
    // single-line calls with literal level
    l = l.replace(new RegExp(`(?<![\\w.])${esc}\\("(debug|info|warn|error)", `, "g"), "logger.$1(");
    // single-line calls with variable level
    l = l.replace(new RegExp(`(?<![\\w.])${esc}\\((level), `, "g"), "logger[$1](");
    // multi-line call: `callee(` at end of line, level literal on next line
    const mm = l.match(new RegExp(`^(\\s*)${esc}\\($`));
    if (mm) {
      const lv = lines[i + 1].match(/^\s*"(debug|info|warn|error)",$/);
      if (!lv) throw new Error(`unexpected multiline at ${rel}:${ln}`);
      out.push(`${mm[1]}logger.${lv[1]}(`); i++; continue;
    }
    out.push(l);
  }
  fs.writeFileSync(file, out.join("\n"));
}
