mkdir -p /tmp/logmig && cat > /tmp/logmig/snap.mjs <<'EOF'
import { pathToFileURL } from "node:url";
const root = process.argv[2];
const modules = await import(pathToFileURL(root + "/src/index.js"));
const { addSink } = await import(pathToFileURL(root + "/src/log.js"));
const inputs = [
  { id: 1, items: [1, 2, 3], ok: true, failed: false },
  { id: 2, items: [], ok: false, failed: true },
  { id: 3, items: [5], ok: false, failed: false },
];
const result = {};
for (const [name, run] of Object.entries(modules)) {
  result[name] = inputs.map((input) => {
    const events = [];
    const remove = addSink((e) => events.push(e));
    let ret, err;
    try { ret = run(input); } catch (e) { err = String(e); }
    remove();
    return { events, ret, err };
  });
}
// also exported forward helpers
for (const f of ["cache19", "refund07"]) {
  const m = await import(pathToFileURL(`${root}/src/services/${f}.js`));
  const calls = []; const events = [];
  const remove = addSink((e) => events.push(e));
  m.forward((...a) => calls.push(a), [1, 2]);
  remove();
  result[f + ".forward"] = { calls, events };
}
console.log(JSON.stringify(result, null, 1));
EOF
