import fs from "node:fs";
import path from "node:path";
const files = process.argv.slice(2);
for (const file of files) {
  let src = fs.readFileSync(file, "utf8");
  let callee;
  if (/import \* as (\w+) from "\.\.\/log\.js";/.test(src)) {
    const ns = src.match(/import \* as (\w+) from "\.\.\/log\.js";/)[1];
    callee = `${ns}\\.log`; // namespace import kept
  } else {
    const m = src.match(/import \{([^}]*)\} from "\.\.\/log\.js";/);
    if (!m) continue;
    const specs = m[1].split(",").map((s) => s.trim());
    const spec = specs.find((s) => /^log(\s+as\s+\w+)?$/.test(s));
    if (!spec) continue;
    callee = spec.includes(" as ") ? spec.split(/\s+as\s+/)[1] : "log";
    const newSpecs = specs.map((s) => (s === spec ? "logger" : s));
    src = src.replace(m[0], `import { ${newSpecs.join(", ")} } from "../log.js";`);
  }
  const prefix = callee.includes(".") ? callee.replace(/\\\.log$/, ".logger") : "logger";
  const lines = src.split("\n");
  let shadowDepth = null; // skip regions where `log` is shadowed
  const out = [];
  for (let i = 0; i < lines.length; i++) {
    let line = lines[i];
    if (shadowDepth === null && (/function \w+\(log[,)]/.test(line) || /^\s*const log = /.test(line))) {
      shadowDepth = /function/.test(line) ? "fn" : "block";
      out.push(line); continue;
    }
    if (shadowDepth === "fn") { if (/^\}/.test(line)) shadowDepth = null; out.push(line); continue; }
    if (shadowDepth === "block") { if (/^\s*\}\s*$/.test(line)) shadowDepth = null; out.push(line); continue; }
    if (/^\s*(\/\/|\/\*|\*)/.test(line) || /const hint = /.test(line)) { out.push(line); continue; }
    const re = new RegExp(`(?<![.\\w])${callee}\\(\\s*(?:"(\\w+)"|(\\w+)),\\s*`, "g");
    line = line.replace(re, (_, lit, expr) => lit ? `${prefix}.${lit}(` : `${prefix}[${expr}](`);
    // multi-line: callee( on its own line, level on next line
    const ml = line.match(new RegExp(`^(\\s*)${callee}\\($`));
    if (ml && /^\s*"(\w+)",\s*$/.test(lines[i + 1])) {
      const lvl = lines[i + 1].match(/"(\w+)"/)[1];
      out.push(`${ml[1]}${prefix}.${lvl}(`); i++; continue;
    }
    out.push(line);
  }
  fs.writeFileSync(file, out.join("\n"));
}
EOF
