import fs from "node:fs";
// Lines (1-based) where `log` is NOT the imported function: forward(log) param, block-local const log.
const skip = {
  "src/services/cache19.js": [5, 6, 7, 8, 9, 10, 11, 12, 13],
  "src/services/refund07.js": [5, 6, 7, 8, 9, 10, 11, 12, 13],
  "src/jobs/order20.js": [9, 10, 11],
  "src/jobs/profile08.js": [9, 10, 11],
};
const files = process.argv.slice(2);
for (const file of files) {
  let src = fs.readFileSync(file, "utf8");
  // callee name per import style
  let callee;
  if (/import \{ log as trace \} from "\.\.\/log\.js";/.test(src)) {
    callee = String.raw`(?<![.\w$])trace`;
    src = src.replace(`import { log as trace } from "../log.js";`, `import { logger } from "../log.js";`);
  } else if (/import \* as logging from "\.\.\/log\.js";/.test(src)) {
    callee = String.raw`(?<![.\w$])logging\.log`;
    src = src.replace(`import * as logging from "../log.js";`, `import { logger } from "../log.js";`);
  } else {
    callee = String.raw`(?<![.\w$])log`;
    src = src.replace(/import \{ (LEVELS, )?log \} from "\.\.\/log\.js";/, (_, l) => `import { ${l ?? ""}logger } from "../log.js";`);
  }
  const lines = src.split("\n");
  const sk = new Set(skip[file] ?? []);
  for (let i = 0; i < lines.length; i++) {
    const n = i + 1, t = lines[i].trim();
    if (sk.has(n) || t.startsWith("//") || t.startsWith("import") || t.includes("const hint =")) continue;
    // single-line literal level
    lines[i] = lines[i].replace(new RegExp(callee + String.raw`\("(debug|info|warn|error)", `, "g"), "logger.$1(");
    // variable level
    lines[i] = lines[i].replace(new RegExp(callee + String.raw`\(level, `, "g"), "logger[level](");
    // multi-line: callee( \n "warn", \n
    if (new RegExp(callee + String.raw`\($`).test(lines[i]) && /^\s*"(debug|info|warn|error)",$/.test(lines[i + 1])) {
      const lvl = lines[i + 1].trim().slice(1, -2);
      lines[i] = lines[i].replace(new RegExp(callee + String.raw`\($`), `logger.${lvl}(`);
      lines.splice(i + 1, 1);
    }
  }
  fs.writeFileSync(file, lines.join("\n"));
}
EOF
node /tmp/logmig/migrate.mjs src/services/*.js src/jobs/*.js && git diff --stat && git diff

