mkdir -p /tmp/logmig && cat > /tmp/logmig/snap.mjs <<'EOF'
import { pathToFileURL } from "node:url";
const root = process.argv[2];
const mods = await import(pathToFileURL(root + "/src/index.js"));
const { addSink } = await import(pathToFileURL(root + "/src/log.js"));
const inputs = [
  { id: 1, items: [1, 2, 3], ok: true, failed: false },
  { id: 2, items: [], ok: false, failed: true },
  { id: 3, items: [5], ok: false, failed: false },
];
const result = {};
for (const [name, run] of Object.entries(mods)) {
  result[name] = inputs.map((input) => {
    const events = [];
    const remove = addSink((e) => events.push(e));
    try { return { out: run(input), events }; } finally { remove(); }
  });
}
console.log(JSON.stringify(result, null, 1));
EOF
node /tmp/logmig/snap.mjs "$PWD" > /tmp/logmig/before.json && wc -c /tmp/logmig/before.json && npm test 2>&1 | tail -5

cat > /tmp/logmig/migrate.mjs <<'EOF'
import fs from "node:fs";
import path from "node:path";
const LEVELS = ["debug", "info", "warn", "error"];
// Lines where `log` is a shadowing local/parameter, not the import.
const SKIP = { "src/jobs/order20.js": [10, 11], "src/jobs/profile08.js": [10, 11], "src/services/cache19.js": [8, 11], "src/services/refund07.js": [8, 11] };
const files = process.argv.slice(2);
for (const file of files) {
  let src = fs.readFileSync(file, "utf8");
  const imp = src.match(/^import (\{ ([^}]*) \}|\* as (\w+)) from "\.\.\/log\.js";$/m);
  if (!imp) continue;
  let callee, newImport;
  if (imp[3]) { callee = `${imp[3]}\\.log`; newImport = `import { logger } from "../log.js";`; }
  else {
    const specs = imp[2].split(",").map((s) => s.trim());
    const logSpec = specs.find((s) => /^log(\s+as\s+\w+)?$/.test(s));
    callee = logSpec.split(/\s+as\s+/).pop();
    newImport = `import { ${specs.filter((s) => s !== logSpec).concat("logger").join(", ")} } from "../log.js";`;
  }
  const skip = SKIP[file] ?? [];
  const re = new RegExp(`(?<![\\w.$])${callee}\\((\\s*)(?:"(\\w+)"|(\\w+)),\\s*`, "g");
  let count = 0;
  const out = src.replace(re, (m, ws, lit, expr, off) => {
    const lineNo = src.slice(0, off).split("\n").length;
    const line = src.split("\n")[lineNo - 1];
    if (skip.includes(lineNo) || line.trim().startsWith("//")) return m;
    if (lit && !LEVELS.includes(lit)) throw new Error(`${file}:${lineNo} unknown level ${lit}`);
    count++;
    return lit ? `logger.${lit}(${ws}` : `logger[${expr}](${ws}`;
  }).replace(imp[0], newImport);
  fs.writeFileSync(file, out);
  console.log(file, count);
}
EOF
node /tmp/logmig/migrate.mjs src/jobs/*.js src/services/*.js

