import fs from "node:fs";
// Line ranges (1-based, inclusive) where `log` is shadowed by a parameter/local.
const shadow = {
  "src/services/cache19.js": [[5, 13]], "src/services/refund07.js": [[5, 13]],
  "src/jobs/order20.js": [[8, 12]], "src/jobs/profile08.js": [[8, 12]],
};
const files = process.argv.slice(2);
for (const f of files) {
  let src = fs.readFileSync(f, "utf8");
  let callee;
  if (/import \* as logging from "\.\.\/log\.js";/.test(src)) callee = "logging\\.log";
  else if (/import \{ log as trace \} from "\.\.\/log\.js";/.test(src)) { callee = "trace"; src = src.replace("{ log as trace }", "{ logger }"); }
  else if (/import \{ (LEVELS, )?log \} from "\.\.\/log\.js";/.test(src)) { callee = "log"; src = src.replace(/import \{ (LEVELS, )?log \}/, "import { $1logger }"); }
  else throw new Error("no import " + f);
  const prefix = callee === "logging\\.log" ? "logging.logger" : "logger";
  const lines = src.split("\n");
  const ranges = shadow[f] || [];
  // operate on whole text but skip shadowed/comment lines: build line offsets
  const re = new RegExp(`(?<![.\\w$])${callee}\\(\\s*(?:"(\\w+)"|([A-Za-z_$][\\w$]*))\\s*,\\s*`, "g");
  let out = "", pos = 0, count = 0;
  const lineOf = (i) => src.slice(0, i).split("\n").length;
  src.replace(re, (m, lit, ident, idx) => {
    const ln = lineOf(idx);
    if (ranges.some(([a, b]) => ln >= a && ln <= b)) return m;
    if (lines[ln - 1].trimStart().startsWith("//")) return m;
    out += src.slice(pos, idx) + (lit ? `${prefix}.${lit}(` : `${prefix}[${ident}](`);
    pos = idx + m.length; count++;
    return m;
  });
  out += src.slice(pos);
  fs.writeFileSync(f, out);
  console.log(f, count);
}
