    if (/function \w+\(log\b/.test(l) || /^\s*\{\s*$/.test(l) && /const log\b/.test(lines[i + 1] || "")) {
      let depth = 0, j = i;
      for (; j < lines.length; j++) {
        for (const c of lines[j]) { if (c === "{") depth++; if (c === "}") depth--; }
        if (depth === 0 && j > i - 0 && lines.slice(i, j + 1).join("").includes("{")) break;
      }
      for (let k = i; k <= j; k++) skip.add(k);
    }
  });
